[{"id":"0aee9fe","elType":"container","settings":{"flex_direction":"column","element_pack_agbg_color_list":[{"_id":"5c3cfe3"},{"start_color":"#567445","end_color":"#1D1BE0","_id":"6047906"}],"ep_widget_cf_colors":"#D30C5C, #0EBCDC, #EAED41, #ED5A78, #DF33DF","ep_widget_cf_shapes":"square|circle","ep_widget_cf_shapes_emoji":"🎃|🎄|💜","ep_widget_cf_shapes_svg":"M167 72c19,-38 37,-56 75,-56 42,0 76,33 76,75 0,76 -76,151 -151,227 -76,-76 -151,-151 -151,-227 0,-42 33,-75 75,-75 38,0 57,18 76,56z|M120 240c-41,14 -91,18 -120,1 29,-10 57,-22 81,-40 -18,2 -37,3 -55,-3 25,-14 48,-30 66,-51 -11,5 -26,8 -45,7 20,-14 40,-30 57,-49 -13,1 -26,2 -38,-1 18,-11 35,-25 51,-43 -13,3 -24,5 -35,6 21,-19 40,-41 53,-67 14,26 32,48 54,67 -11,-1 -23,-3 -35,-6 15,18 32,32 51,43 -13,3 -26,2 -38,1 17,19 36,35 56,49 -19,1 -33,-2 -45,-7 19,21 42,37 67,51 -19,6 -37,5 -56,3 25,18 53,30 82,40 -30,17 -79,13 -120,-1l0 41 -31 0 0 -41z|M449.4 142c-5 0-10 .3-15 1a183 183 0 0 0-66.9-19.1V87.5a17.5 17.5 0 1 0-35 0v36.4a183 183 0 0 0-67 19c-4.9-.6-9.9-1-14.8-1C170.3 142 105 219.6 105 315s65.3 173 145.7 173c5 0 10-.3 14.8-1a184.7 184.7 0 0 0 169 0c4.9.7 9.9 1 14.9 1 80.3 0 145.6-77.6 145.6-173s-65.3-173-145.7-173zm-220 138 27.4-40.4a11.6 11.6 0 0 1 16.4-2.7l54.7 40.3a11.3 11.3 0 0 1-7 20.3H239a11.3 11.3 0 0 1-9.6-17.5zM444 383.8l-43.7 17.5a17.7 17.7 0 0 1-13 0l-37.3-15-37.2 15a17.8 17.8 0 0 1-13 0L256 383.8a17.5 17.5 0 0 1 13-32.6l37.3 15 37.2-15c4.2-1.6 8.8-1.6 13 0l37.3 15 37.2-15a17.5 17.5 0 0 1 13 32.6zm17-86.3h-82a11.3 11.3 0 0 1-6.9-20.4l54.7-40.3a11.6 11.6 0 0 1 16.4 2.8l27.4 40.4a11.3 11.3 0 0 1-9.6 17.5z","section_parallax_elements":[],"element_pack_tile_scroll_elements":[],"ep_display_conditions":[],"container_type":"grid","presetTitle":"Izgara","presetIcon":"eicon-container-grid","grid_gaps":{"column":"5","row":"5","isLinked":true,"unit":"px"},"css_classes":"delf-scroll"},"elements":[{"id":"2c0e450","elType":"widget","settings":{"html":"<div class="delf-card">
 <h3 class="delf-title">DELF A1</h3>
 <div class="delf-ring">
 <canvas id="delfA1"></canvas>
 <div class="delf-center">
 <div class="delf-level">DELF A1</div>
 </div>
 </div>
 <ul class="delf-legend" aria-label="Puan aralıkları">
 <li><span style="background:#bfe39a"></span>70–79</li>
 <li><span style="background:#7ccf8f"></span>80–89</li>
 <li><span style="background:#54be83"></span>90–100</li>
 </ul>
</div>

<style>
 .delf-card{
 display:grid; gap:12px; place-items:center;
 padding:20px; border-radius:16px;
 background:linear-gradient(180deg,#ffffff 0%, #f7faf9 100%);
 box-shadow:0 8px 24px rgba(0,0,0,.06);
 max-width:320px; margin:auto;
 }
 .delf-title{ margin:0; font-weight:800; letter-spacing:.3px; }
 .delf-ring{ position:relative; width:min(260px,70vw); aspect-ratio:1; }
 .delf-center{
 position:absolute; inset:0; display:grid; place-content:center; text-align:center;
 pointer-events:none;
 }
 .delf-level{ font-size:20px; font-weight:800; color:#333; }
 .delf-legend{
 list-style:none; display:flex; gap:12px; padding:0; margin:4px 0 0;
 flex-wrap:wrap; justify-content:center; font-size:12px; opacity:.9;
 }
 .delf-legend li{ display:flex; align-items:center; gap:6px; }
 .delf-legend li span{
 width:10px; height:10px; border-radius:3px; display:inline-block;
 box-shadow: inset 0 0 0 1px rgba(0,0,0,.06);
 }
</style>

<!-- Bu iki script sayfada SADECE bir kez olmalı -->
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels@2"></script>

<script>
(function(){
 const canvas = document.getElementById('delfA1');
 const ctx = canvas.getContext('2d');

 // Canvas'ın gerçek piksel boyutunu CSS boyutuyla eşitle (kritik)
 function syncCanvasSize() {
 const w = canvas.clientWidth;
 const h = canvas.clientHeight; // kare zaten; yine de ayrı ölçüyoruz
 canvas.width = Math.round(w);
 canvas.height = Math.round(h);
 }
 syncCanvasSize();

 // Gradient helper
 function grad(top, bottom){
 const g = ctx.createLinearGradient(0,0,0,canvas.height);
 g.addColorStop(0, top);
 g.addColorStop(1, bottom);
 return g;
 }

 const labels = ['70–79','80–89','90–100'];
 const values = [30, 30, 40];
 const fills = [
 grad('#bfe39a','#e8f5e5'),
 grad('#7ccf8f','#d9f1e1'),
 grad('#54be83','#d0eddc')
 ];

 const chart = new Chart(ctx, {
 type: 'doughnut',
 data: { labels, datasets: [{ data: values, backgroundColor: fills, borderWidth: 0, hoverOffset: 6 }] },
 options: {
 responsive: true, // Chart.js kendi resize'ını yapacak
 maintainAspectRatio: false, // Çünkü boyutu kapsayıcıdan alıyoruz (kare)
 cutout: '64%',
 rotation: -0.5 * Math.PI,
 plugins: {
 legend: { display: false },
 tooltip: { callbacks: { label: (c) => `${c.label}: ${c.parsed}%` } },
 datalabels: {
 color: '#1f3d2a',
 formatter: (v, ctx) => `${ctx.chart.data.labels[ctx.dataIndex]}\n${v}%`,
 font: (ctx) => ({ weight: 700, size: ctx.dataset.data[ctx.dataIndex] < 8 ? 9 : 11 }),
 align: 'center', anchor: 'center', clamp: true
 }
 },
 animation: { animateRotate: true, duration: 1100, easing: 'easeOutQuart' }
 },
 plugins: [ChartDataLabels]
 });

 // Pencere boyutu değişince önce canvas'ı eşitle, sonra chart'ı yeniden boyutlandır
 window.addEventListener('resize', () => {
 syncCanvasSize();
 chart.resize();
 });
})();
