 <!-- A1 -->
 <div class="chart-card">
 <h3 class="chart-title">DELF A1</h3>
 <div class="chart-ring"><canvas id="chartA1"></canvas></div>
 </div>
 <!-- B1 -->
 <div class="chart-card">
 <h3 class="chart-title">DELF B1</h3>
 <div class="chart-ring"><canvas id="chartB1"></canvas></div>
 </div>
 <!-- C1 -->
 <div class="chart-card">
 <h3 class="chart-title">DALF C1</h3>
 <div class="chart-ring"><canvas id="chartC1"></canvas></div>
 </div>
 <!-- A2 -->
 <div class="chart-card">
 <h3 class="chart-title">DELF A2</h3>
 <div class="chart-ring"><canvas id="chartA2"></canvas></div>
 </div>
 <!-- B2 -->
 <div class="chart-card">
 <h3 class="chart-title">DELF B2</h3>
 <div class="chart-ring"><canvas id="chartB2"></canvas></div>
 </div>
 <!-- C2 -->
 <div class="chart-card">
 <h3 class="chart-title">DALF C2</h3>
 <div class="chart-ring"><canvas id="chartC2"></canvas></div>
 </div>
</section>

<style>
/* Masaüstü grid */
.chart-scroll{
 display:grid;
 grid-template-columns: repeat(auto-fit, minmax(260px,1fr));
 gap:24px;
 padding:10px;
}
.chart-card{
 display:grid; gap:12px; place-items:center;
 padding:20px; border-radius:16px;
 background:linear-gradient(180deg,#ffffff 0%, #f7faf9 100%);
 box-shadow:0 8px 24px rgba(0,0,0,.06);
}
.chart-title{margin:0;font-weight:800}
.chart-ring{position:relative;width:min(260px,70vw);aspect-ratio:1}
.chart-ring canvas{display:block;width:100%;height:100%}



/* Mobilde yatay kaydırma */
@media (max-width:768px){
 .chart-scroll{
 display:flex;
 gap:16px;
 overflow-x:auto;
 scroll-snap-type:x mandatory;
 -webkit-overflow-scrolling:touch;
 padding:10px 6px;
 }
 .chart-card{
 flex:0 0 80%;
 max-width:320px;
 scroll-snap-align:start;
 }
}
</style>



<script>
(function(){
 // 1) ETİKETLER (5 adet)
 const LABELS = ['50–59','60–69','70–79','80–89','90–100'];

 // 2) VERİLER — eksik olanları yazmana gerek yok; pad edilecek
 const DATA = {
 A1: [0, 0, 30, 30, 40],
 A2: [0, 5, 32, 42, 21],
 B1: [8, 12, 28, 20, 32],
 B2: [0, 34, 32, 24, 10],
 C1: [21, 42, 37, 0, 0], // kendi gerçek değerlerinle değiştir
 C2: [72, 14, 14, 0, 0] // kendi gerçek değerlerinle değiştir
 };

 // 3) Canvas piksel boyutunu CSS boyutuyla eşitle (kaymayı önler)
 function syncCanvas(canvas){
 const w = canvas.clientWidth, h = canvas.clientHeight;
 canvas.width = Math.round(w);
 canvas.height = Math.round(h);
 }

 // 4) 5 renk (etiketlerle birebir)
 function makeColors(ctx,h){
 const G=(a,b)=>{const g=ctx.createLinearGradient(0,0,0,h); g.addColorStop(0,a); g.addColorStop(1,b); return g;};
 return [
 G('#f5e86a','#fff9d6'), // 50–59
 G('#b2f2cf','#dcfae7'), // 60–69
 G('#80e1af','#c8f5d8'), // 70–79
 G('#4fd18f','#aef0c6'), // 80–89
 G('#2db06f','#95e9b5') // 90–100 (daha koyu)
 ];
 }

 // 5) Kısa/veri dizilerini 5 elemana pad et (eksikler 0)
 function padToFive(arr){
 const out = (arr || []).slice(0,5);
 while(out.length < 5) out.push(0);
 return out;
 }

 function drawChart(id, values){
 const canvas = document.getElementById(id);
 if(!canvas) return;
 syncCanvas(canvas);
 const ctx = canvas.getContext('2d');

 const data5 = padToFive(values);

 new Chart(ctx, {
 type:'doughnut',
 data:{
 labels: LABELS,
 datasets:[{
 data: data5,
 backgroundColor: makeColors(ctx, canvas.height),
 borderWidth:0,
 hoverOffset:6
 }]
 },
 options:{
 responsive:true,
 maintainAspectRatio:false,
 cutout:'64%',
 rotation:-0.5*Math.PI,
 plugins:{
 legend:{
 display:true,
 position:'bottom',
 align:'center',
 labels:{
 usePointStyle:true,
 pointStyle:'circle',
 boxWidth:8,
 boxHeight:8,
 padding:16,
 color:'#2b3c33',
 font:{ size:12, weight:'600' }
 }
 },
 tooltip:{callbacks:{ label:(c)=> `${c.label}: ${c.parsed}%` }},
 datalabels:{
 color:'#1f3d2a',
 formatter:(v, ctx)=>{
 if(!v) return ''; // 0 olan dilimde etiket gösterme
 return `${ctx.chart.data.labels[ctx.dataIndex]}\n${v}%`;
 },
 font:(ctx)=>({weight:700, size: ctx.dataset.data[ctx.dataIndex] < 8 ? 9 : 11}),
 align:'center', anchor:'center', clamp:true
 }
 },
 animation:{animateRotate:true, duration:1000, easing:'easeOutQuart'}
 },
 plugins:[ChartDataLabels]
 });

 window.addEventListener('resize', ()=>{ syncCanvas(canvas); });
 }

 // 6) Çizimler — id sırası HTML'deki canvas id'lerinle aynı olmalı
 drawChart('chartA1', DATA.A1);
 drawChart('chartA2', DATA.A2);
 drawChart('chartB1', DATA.B1);
 drawChart('chartB2', DATA.B2);
 drawChart('chartC1', DATA.C1);
 drawChart('chartC2', DATA.C2);
})();
</script>

