<style>
/* ---------- Kart bileşeni (ortak) ---------- */
.delf-card{
 display:grid; gap:12px; place-items:center;
 padding:16px; border-radius:16px;
 background:linear-gradient(180deg,#ffffff 0%, #f7faf9 100%);
 box-shadow:0 8px 24px rgba(0,0,0,.06);
}
.delf-title{ margin:0; font-weight:800; letter-spacing:.3px; }
.delf-ring{ position:relative; width:min(260px,70vw); aspect-ratio:1; }
.delf-center{ position:absolute; inset:0; display:grid; place-content:center; text-align:center; pointer-events:none; }
.delf-level{ font-size:20px; font-weight:800; color:#333; }
.delf-legend{ list-style:none; display:flex; gap:12px; padding:0; margin:4px 0 0; flex-wrap:wrap; justify-content:center; font-size:12px; opacity:.9; }
.delf-legend li{ display:flex; align-items:center; gap:6px; }
.delf-legend li span{ width:10px; height:10px; border-radius:3px; display:inline-block; box-shadow: inset 0 0 0 1px rgba(0,0,0,.06); }

/* ---------- Mobil varsayılan (<768px): yatay kaydırma ---------- */
.delf-scroll{
 display:flex !important;
 gap:12px;
 overflow-x:auto; padding:0 8px 8px;
 scroll-snap-type:x mandatory;
 -webkit-overflow-scrolling:touch;
}
.delf-scroll .delf-card{
 flex:0 0 auto;
 min-width:260px;
 scroll-snap-align:start;
}
@media (max-width: 767.98px){
 .delf-card{ padding:14px; gap:8px; }
 .delf-ring{ width: clamp(140px, 55vw, 200px); }
 .delf-level{ font-size:16px; }
 .delf-title{ font-size:17px; }
 .delf-legend{ font-size:11px; gap:8px; }
 /* İstersen daha da kısalt: */
 /* .delf-center{ display:none; } */
}

/* ---------- Tablet (≥768px): 2 sütun grid ---------- */
@media (min-width: 768px){
 .delf-scroll{
 display:grid !important;
 grid-template-columns: repeat(2, 1fr) !important;
 gap:20px !important;
 width:100% !important;
 align-items:stretch;
 overflow:visible; /* mobildeki yatay scroll'u kapat */
 }
 .delf-scroll > .delf-card{
 width:100% !important;
 }
}

/* ---------- Masaüstü (≥1200px): 3 sütun grid ---------- */
@media (min-width: 1200px){
 .delf-scroll{
 grid-template-columns: repeat(3, 1fr) !important;
 gap:24px !important;
 }
}
</style>


<!-- Bu iki script sayfada SADECE bir kez olmalı -->
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<script src="https://cdn.jsdelivr.net/npm/chartjs-plugin-datalabels@2"></script>

<script>
(function(){
 if (!window.Chart) return;

 // Her canvas için tek noktadan kurulum
 const chartsConfig = [
 {
 id: 'delfA1',
 labels: ['70–79','80–89','90–100'],
 data: [30, 30, 40],
 colors: [['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 },
 {
 id: 'delfB1',
 labels: ['60–69','70–79','80–89','90–100'],
 data: [20, 30, 25, 25],
 colors: [['#f5e86a','#fff9d2'], ['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 },
 {
 id: 'delfC1',
 labels: ['50–59','60–69','70–79'],
 data: [25, 35, 40],
 colors: [['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 },
	 {
 id: 'delfA2',
 labels: ['60–69','70–79','80–89','90–100'],
 data: [5, 32, 42, 21],
 colors: [['#f5e86a','#fff9d2'], ['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 },
 {
 id: 'delfB2',
 labels: ['60–69','70–79','80–89','90–100'],
 data: [34, 32, 24, 10],
 colors: [['#f5e86a','#fff9d2'], ['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 },
 {
 id: 'delfC2',
 labels: ['50–59','60–69','70–79'],
 data: [72, 14, 14],
 colors: [['#bfe39a','#e8f5e5'], ['#7ccf8f','#d9f1e1'], ['#54be83','#d0eddc']]
 }
 ];

 const dpr = Math.max(1, window.devicePixelRatio || 1);

 function setupChart({id, labels, data, colors}){
 const canvas = document.getElementById(id);
 if(!canvas) return;

 const ctx = canvas.getContext('2d');

 function sizeCanvas(){
 const w = canvas.clientWidth || 260;
 const h = canvas.clientHeight || w;
 canvas.width = Math.round(w * dpr);
 canvas.height = Math.round(h * dpr);
 ctx.setTransform(dpr,0,0,dpr,0,0);
 }

 function grad(top, bottom){
 const g = ctx.createLinearGradient(0,0,0,(canvas.clientHeight||260));
 g.addColorStop(0, top); g.addColorStop(1, bottom);
 return g;
 }

 const bg = colors.map(([t,b]) => grad(t,b));
 const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

 sizeCanvas();
 const chart = new Chart(ctx, {
 type: 'doughnut',
 data: { labels, datasets: [{ data, backgroundColor: bg, borderWidth: 0, hoverOffset: 6 }] },
 options: {
 responsive: true,
 maintainAspectRatio: false,
 cutout: '64%',
 rotation: -0.5 * Math.PI,
 plugins: {
 legend: { display: false },
 tooltip: { callbacks: { label: (c) => `${c.label}: ${c.parsed}%` } },
 datalabels: {
 color: '#1f3d2a',
 formatter: (v, ctx) => `${ctx.chart.data.labels[ctx.dataIndex]}\n${v}%`,
 font: (ctx) => ({ weight:700, size: ctx.dataset.data[ctx.dataIndex] < 8 ? 9 : 11 }),
 align: 'center', anchor: 'center', clamp: true
 }
 },
 animation: prefersReduce ? false : { animateRotate: true, duration: 900, easing: 'easeOutQuart' }
 },
 plugins: [ChartDataLabels]
 });

 const onResize = () => { sizeCanvas(); chart.resize(); };
 window.addEventListener('resize', onResize, { passive:true });

 return { chart, onResize };
 }

 // Görünür olunca kur – performans
 const created = new Map();
 const io = new IntersectionObserver((entries)=>{
 entries.forEach(e=>{
 if(!e.isIntersecting) return;
 const id = e.target.id;
 if(created.has(id)) return;
 const cfg = chartsConfig.find(c => c.id === id);
 const handle = setupChart(cfg);
 if(handle) created.set(id, handle);
 io.unobserve(e.target);
 });
 }, { threshold:.2 });

 chartsConfig.forEach(cfg => {
 const el = document.getElementById(cfg.id);
 if (el) io.observe(el);
 });
})();
